#!/usr/bin/env python
# ── GENERATED by matsci-kb-kit build/build_kit.py — DO NOT EDIT (真源见 kit.yaml) ──
r"""给缺 `si_status` 的 source 卡补判定 —— 判据来自 `lit_ingest.detect_si_from_md` / `lit_si.scan_pdf`。

背景（2026-10-25 体检 §3.4）
---------------------------
842 张 source 型页里 8 张**根本没有 `si_status` 键**（不是 missing，是没判过）。
没判过的与「判过、确无 SI」混在同一张统计表里，会让 `si-missing` 缺口看起来比实际更小——
这正是 CLAUDE.md 说的「缺省值最危险：它从不被写出来，因而不被审查」。

判据（**不新写一套**）
----------------------
优先用 `lit_ingest.detect_si_from_md(head, raw/text 提取件)`：
  1. 提取件头部页区间声明（`共 N 页（正文 1-a 页，补充材料 b-c 页）`）
  2. 头部声明「无补充材料」→ 落到全文扫描
  3. 全文扫描 SI 声明 / `Fig. S#`・`Table S#` 引用（`lit_si`）
  4. 独立 SI 文件（`raw/pdf/si/<stem>.si.<ext>`）
无 `raw/text/` 提取件但有 PDF 时，直接 `lit_si.scan_pdf(PDF)`（与 `lit_si scan <PDF>` 同口径）。

🔴 三条「不写」红线（都是本库踩过的坑）
--------------------------------------
  a. **判不出就不写**：三类证据都没有时 detect 返回 `missing` + 依据「未判定」。
     写进卡片等于**断言一个从未验证的否定**（旧版 build_card 硬写 missing 就是这个病）。
  b. **`raw/clippings/` 与 PDF 不能当 `raw/text/` 传**：剪藏是 1 页的公号文，
     拿它全文扫描必然「无 SI 声明」⇒ 假 not_applicable。实测本轮 4/8 张就是被剪藏误导的。
  c. **扫描页数 < 3 时不下结论**：1 页扫描不是「全文」，据此判「无 SI」是 denominator 出错。
     这种情形报 SKIP，等补到全文提取件再判。

用法
----
    python tools/qc_si_backfill.py             # 干跑
    python tools/qc_si_backfill.py --apply     # 落盘（备份 .qc_backup_YYYYMMDD/，写后复算）
    python tools/qc_si_backfill.py --recheck   # 复判已写 missing/partial 的卡（只允许升级到 present）
    python tools/qc_si_backfill.py --recheck --apply
    python tools/qc_si_backfill.py --selftest  # 夹具反算

🆕 2026-10-26 `--recheck`（为什么必须单独一个开关）
------------------------------------------------
浏览器兜底（`lit_browser_fetch`）拿到 SI 后，**卡片自己不会变**：卡上仍写 `si_status: missing`，
而 `raw/pdf/si/<stem>.si.pdf` 已存在。默认模式只看"没有 si_status 键"的卡，扫不到这种矛盾。
`--recheck` 把 missing/partial 的卡重判一遍，但**只有"独立 SI 文件存在"这一条硬证据**
能改写卡片（升级到 present）；复判成 not_applicable/missing 一律不写——
否则等于用"这一遍没看见"覆盖上一遍的判断。
"""
import os
import re
import sys
import glob
import shutil
import datetime

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
os.chdir(ROOT)
sys.path.insert(0, "tools")
from kb_lib import (read_text, split_frontmatter, parse_frontmatter,  # noqa: E402
                    join_frontmatter, write_text_verified, console_encoding,
                    load_lit_config)

console_encoding()

UNKNOWN_MARK = "未判定"
MIN_PAGES = 3          # 少于这么多页的「全文扫描」不构成判定依据
TEXT_DIR = "raw/text"
PDF_DIR = "raw/pdf"


# ---------------------------------------------------------------- 定位证据文件
def _clean(entry):
    t = str(entry).replace("\\|", "|").split("|")[0].strip().strip('"').strip("'")
    t = t[2:] if t.startswith("[[") else t
    t = t[:-2] if t.endswith("]]") else t
    return t.replace("\\", "").strip()


def link_paths(fm):
    """把 `sources:` 里的库内路径按类别分开（只认真实存在的文件）。"""
    srcs = fm.get("sources") or []
    if isinstance(srcs, str):
        srcs = [srcs]
    out = {"text": "", "pdf": "", "clip": ""}
    for s in srcs:
        t = _clean(s)
        if not t.endswith(".md") and not t.lower().endswith(".pdf"):
            continue
        if not os.path.exists(t):
            continue
        tt = t.replace("\\", "/")
        if tt.startswith(TEXT_DIR + "/") and not out["text"]:
            out["text"] = t
        elif tt.startswith(PDF_DIR + "/") and not out["pdf"]:
            out["pdf"] = t
        elif tt.startswith("raw/clippings/") and not out["clip"]:
            out["clip"] = t
    return out


def head_of(md_path, n=4000):
    """与 `lit_ingest.build_card` 同口径：**去掉 frontmatter 后**取前 4000 字符。"""
    t = read_text(md_path)
    a, b = split_frontmatter(t)
    body = b if a else t
    return body[:n]


# ---------------------------------------------------------------- 判定（纯函数）
def decide_from_head(head, md_path, detect):
    """文本路径：detect 注入以便 selftest 反算 → (status|None, evidence|原因)。"""
    got = detect(head, md_path, None)
    st = got.get("si_status")
    ev = got.get("si_evidence") or ""
    if st not in ("present", "partial", "missing", "not_applicable"):
        return None, "detect 返回非法状态 %r" % (st,)
    if st == "missing" and UNKNOWN_MARK in ev:
        return None, ev
    if st == "not_applicable":
        m = re.search(r"（(\d+)\s*页）", ev)
        if m and int(m.group(1)) < MIN_PAGES:
            return None, "全文扫描只有 %s 页（< %d），不构成判定依据：%s" % (
                m.group(1), MIN_PAGES, ev)
    return st, ev


def decide_from_pdf_verdict(v, si_hit=""):
    """PDF 路径：把 `lit_si.scan_pdf` 的返回值翻成 (status, evidence)。纯函数。"""
    if si_hit:
        return "present", "已获取独立 SI 文件：" + os.path.basename(si_hit)
    verdict = (v or {}).get("verdict")
    pages = (v or {}).get("pages") or 0
    if verdict == "has_si":
        return "missing", ("PDF 全扫（%s 页）有 SI 证据（声明 %d 处 / S-编号引用 %s 处），"
                           "但未取到独立文件（无 raw/text 提取件）"
                           % (pages, len(v.get("decls") or []), v.get("srefs")))
    if verdict == "no_si":
        if pages and pages < MIN_PAGES:
            return None, "PDF 全扫只有 %s 页（< %d），不构成判定依据" % (pages, MIN_PAGES)
        return "not_applicable", ("PDF 全扫（%s 页）：无 SI 声明、无 Fig./Table S# 引用 ⇒ 判定无 SI"
                                  "（无 raw/text 提取件，故直接扫原文 PDF）" % pages)
    return None, "PDF 全扫未得出结论（verdict=%r 页数=%s）" % (verdict, pages)


# ---------------------------------------------------------------- 写回
def insert_fields(a, b, status, note):
    """纯函数：把 si_status / si_note 插进 frontmatter 文本。返回新全文。"""
    if not a:
        raise ValueError("frontmatter 不可解析，拒绝写入")
    a2 = a
    if re.search(r"^si_status\s*:", a2, re.M):
        a2 = re.sub(r"^si_status\s*:.*$", "si_status: " + status, a2, count=1, flags=re.M)
    else:
        if not re.search(r"^type\s*:", a2, re.M):
            raise ValueError("frontmatter 里没有 type: 字段，拒绝盲插")
        a2 = re.sub(r"^(type\s*:.*)$", lambda m: m.group(1) + "\nsi_status: " + status,
                    a2, count=1, flags=re.M)
    if note:
        line = "si_note: " + '"' + note.replace('"', "'") + '"'
        if re.search(r"^si_note\s*:", a2, re.M):
            a2 = re.sub(r"^si_note\s*:.*$", line, a2, count=1, flags=re.M)
        else:
            a2 = re.sub(r"^(si_status\s*:.*)$", lambda m: m.group(1) + "\n" + line,
                        a2, count=1, flags=re.M)
    new = join_frontmatter(a2.strip("\n"), b)
    if not split_frontmatter(new)[0]:
        raise ValueError("写入后会破坏 frontmatter，已中止")
    return new


def write_fields(page, status, note):
    """磁盘版：读 → insert_fields → 返回 (旧文本, 新文本)。"""
    t = read_text(page)
    a, b = split_frontmatter(t)
    return t, insert_fields(a, b, status, note)


# ---------------------------------------------------------------- 主流程
def needs_judgement(fm, recheck=False):
    """这张卡该不该判？
    · 无 `si_status` 键 → 判（本工具原始职责）
    · `--recheck` 且现值是 missing/partial → 复判（2026-10-26 新增：浏览器兜底拿到 SI 后
      卡片仍写着 missing，与实际文件矛盾；这类只能靠**复判**发现）
    · 现值 present / not_applicable → 永不重判（前者已有文件，后者是核查过的"确无"）
    """
    if "si_status" not in fm:
        return True
    if not recheck:
        return False
    return str(fm.get("si_status") or "").strip() in ("missing", "partial")


def is_upgrade(cur, new):
    """复判结果是否允许落盘。
    🔴 复判**只允许升级到 present**（有独立 SI 文件这一条硬证据）；
    把 missing 复判成 not_applicable / missing 不得写——那等于用"这一遍没看见"
    覆盖上一遍的判断，是本库最忌讳的"凭缺省值下断言"。
    """
    cur = str(cur or "").strip()
    if not cur:
        return True                       # 首次判定，任何结论都可写（由 decide_* 把关）
    return new == "present" and cur in ("missing", "partial")


def judge_card(card, detect, scan_pdf, find_si, recheck=False):
    """单卡判定 → dict(status, evidence, basis) 或 dict(status=None, reason)。"""
    a, _b = split_frontmatter(read_text(card))
    fm = parse_frontmatter(a)
    if not needs_judgement(fm, recheck):
        return None
    paths = link_paths(fm)
    if paths["text"]:
        st, ev = decide_from_head(head_of(paths["text"]), paths["text"], detect)
        return {"status": st, "evidence": ev, "basis": "raw/text 提取件"}
    if paths["pdf"]:
        v = scan_pdf(paths["pdf"])
        si = find_si(paths["pdf"])
        st, ev = decide_from_pdf_verdict(v, si)
        return {"status": st, "evidence": ev, "basis": "原文 PDF 全扫（无提取件）"}
    why = "既无 raw/text 提取件也无 raw/pdf；只有剪藏（%s）" % (
        "有" if paths["clip"] else "无")
    return {"status": None, "reason": why}


def run(dry_run=True, recheck=False):
    from lit_ingest import detect_si_from_md, find_si_file
    import lit_si
    today = datetime.date.today().isoformat()
    todo, skipped = [], []
    for p in sorted(glob.glob("wiki/sources/*.md")):
        a, _b = split_frontmatter(read_text(p))
        if not a:
            continue
        fm = parse_frontmatter(a)
        if not needs_judgement(fm, recheck):
            continue
        cur = str(fm.get("si_status") or "").strip()
        r = judge_card(p, detect_si_from_md, lit_si.scan_pdf, find_si_file, recheck=recheck)
        if r is None:
            continue
        if r["status"] is None:
            skipped.append((p, r["reason"]))
        elif not is_upgrade(cur, r["status"]):
            skipped.append((p, "复判未取得新证据（现值 %s，复判仍判 %s）" % (cur, r["status"])))
        else:
            todo.append((p, r["status"], r["evidence"], r["basis"]))
    head = ("复判 missing/partial 卡：可升级 %d 张" if recheck
            else "缺 si_status 的卡：待补 %d 张")
    print((head + " / 判不了留人工 %d 张") % (len(todo), len(skipped)))
    for p, st, ev, basis in todo:
        print("  [%s] %s\n       依据（%s）：%s" % (st, os.path.basename(p)[:-3], basis, ev))
    for p, why in skipped:
        print("  [SKIP-证据不足] %s\n       原因：%s" % (os.path.basename(p)[:-3], why))

    if dry_run:
        print("\n[干跑] 未写盘。确认后加 --apply。")
        return 0
    bak = ".qc_backup_%s" % datetime.date.today().strftime("%Y%m%d")
    n_ok = 0
    for p, st, ev, basis in todo:
        note = ("%s 补判定（%s）：%s；正文/source_reliability 中关于 SI 的旧记述若与之矛盾，"
                "以本条与 si_status 为准" % (today, basis, ev))
        _old, new = write_fields(p, st, note)
        dst = os.path.join(bak, p.replace("\\", "/"))
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(p, dst)
        ok, detail = write_text_verified(p, new, quiet=False, require_frontmatter=True)
        if not ok:
            print("  [!] %s 写入失败：%s" % (p, detail))
            continue
        fm2 = parse_frontmatter(split_frontmatter(read_text(p))[0])
        if fm2.get("si_status") != st:
            print("  [!] %s 写后复算不一致" % p)
            continue
        n_ok += 1
    print("\n落盘 %d 张（备份 %s/）" % (n_ok, bak))
    return 0


# ---------------------------------------------------------------- selftest
def run_selftest():
    ok = True
    n = [0]

    def chk(name, cond, extra=""):
        nonlocal ok
        n[0] += 1
        print(("  PASS  " if cond else "  FAIL  ") + name + (("  " + extra) if extra else ""))
        if not cond:
            ok = False

    print("== qc_si_backfill --selftest ==")
    card = ("---\ntype: source\ntags: [t]\nsummary: \"s\"\n"
            "sources:\n  - \"[[raw/text/能源/x.md]]\"\n---\n# T\n\n正文。\n")

    def _d(status, ev):
        return lambda head, md, cfg: {"si_status": status, "si_evidence": ev}

    st, ev = decide_from_head("", "raw/text/能源/x.md",
                              _d("not_applicable", "全文扫描（12 页）：无 SI 声明"))
    chk("not_applicable 被接受（≥3 页扫描）", st == "not_applicable", str(st))
    st, _ = decide_from_head("", "raw/text/能源/x.md",
                             _d("present", "已获取独立 SI 文件：x.si.pdf"))
    chk("present 被接受（有文件证据）", st == "present", str(st))
    st, _ = decide_from_head("", "raw/text/能源/x.md",
                             _d("missing", "提取件头部无页区间信息（旧格式提取件），SI 有无未判定"))
    chk("『未判定』→ 不写（避免凭空造 missing）", st is None, str(st))
    # 🔴 本轮实测踩的坑：剪藏是 1 页 → 扫出「无 SI」是假阴性
    st, ev = decide_from_head("", "raw/clippings/x.md",
                              _d("not_applicable", "全文扫描（1 页）：无 SI 声明、无 Fig./Table S# 引用 ⇒ 判定无 SI"))
    chk("1 页扫描 → 拒绝下结论（剪藏假阴性回归夹具）", st is None, str(st))

    st, ev = decide_from_pdf_verdict({"verdict": "no_si", "pages": 12})
    chk("PDF 路径 no_si(12 页) → not_applicable", st == "not_applicable", str(st))
    st, ev = decide_from_pdf_verdict({"verdict": "no_si", "pages": 1})
    chk("PDF 路径 no_si(1 页) → 拒绝", st is None, str(st))
    st, ev = decide_from_pdf_verdict({"verdict": "has_si", "pages": 10,
                                      "decls": ["a", "b"], "srefs": 9})
    chk("PDF 路径 has_si → missing", st == "missing", str(st))
    st, ev = decide_from_pdf_verdict({"verdict": "unknown", "pages": 0})
    chk("PDF 路径 unknown → 不写", st is None, str(st))
    st, ev = decide_from_pdf_verdict({"verdict": "no_si", "pages": 12}, si_hit="si/x.si.pdf")
    chk("有独立 SI 文件优先 → present", st == "present", str(st))

    # 🆕 2026-10-26 `--recheck` 的两道闸门（纯函数，逐条正反例）
    chk("无 si_status 键 → 默认模式也判",
        needs_judgement({"type": "source"}) is True)
    chk("默认模式不碰已有 si_status 的卡",
        needs_judgement({"si_status": "missing"}) is False)
    chk("--recheck 会复判 missing",
        needs_judgement({"si_status": "missing"}, recheck=True) is True)
    chk("--recheck 会复判 partial",
        needs_judgement({"si_status": "partial"}, recheck=True) is True)
    chk("反例：--recheck 不碰 present（已有文件，重判只会倒退）",
        needs_judgement({"si_status": "present"}, recheck=True) is False)
    chk("反例：--recheck 不碰 not_applicable（核查过的『确无』）",
        needs_judgement({"si_status": "not_applicable"}, recheck=True) is False)

    chk("首次判定任何结论都可写",
        is_upgrade("", "not_applicable") and is_upgrade("", "missing"))
    chk("missing → present 允许（复判的唯一升级方向）",
        is_upgrade("missing", "present") and is_upgrade("partial", "present"))
    chk("反例：missing → not_applicable 不允许（不得用『没看见』覆盖旧判断）",
        not is_upgrade("missing", "not_applicable"))
    chk("反例：missing → missing 不写（无变化不落盘）",
        not is_upgrade("missing", "missing"))
    chk("反例：present → 任何值都不写",
        not is_upgrade("present", "present") and not is_upgrade("present", "missing"))

    # 写回
    a0, b0 = split_frontmatter(card)
    new = insert_fields(a0, b0, "not_applicable", "2026-10-25 补判定：全文扫描无 SI")
    a2 = split_frontmatter(new)[0]
    f2 = parse_frontmatter(a2)
    chk("si_status 已写入", f2.get("si_status") == "not_applicable", str(f2.get("si_status")))
    chk("si_note 已写入", "补判定" in str(f2.get("si_note")), str(f2.get("si_note"))[:50])
    chk("type 未被破坏", f2.get("type") == "source")
    chk("后续键未被吞（summary 仍在）", f2.get("summary") == "s")
    chk("sources 列表未被破坏", f2.get("sources") == ["[[raw/text/能源/x.md]]"],
        str(f2.get("sources")))
    new2 = insert_fields(a2, split_frontmatter(new)[1], "not_applicable", "2026-10-25 补判定：x")
    chk("幂等：si_status 只有一行", new2.count("\nsi_status:") == 1, str(new2.count("\nsi_status:")))
    try:
        insert_fields("tags: [a]\n", "\n# T\n", "missing", "n")
        chk("无 type: 时拒绝盲插", False, "未抛异常")
    except ValueError:
        chk("无 type: 时拒绝盲插", True)

    print("\n%s (%d 项断言)" % ("全部 PASS" if ok else "有 FAIL", n[0]))
    return 0 if ok else 1


def main():
    args = sys.argv[1:]
    if "--help" in args or "-h" in args:
        print(__doc__)
        return 0
    if "--selftest" in args:
        return run_selftest()
    return run(dry_run="--apply" not in args, recheck="--recheck" in args)


if __name__ == "__main__":
    sys.exit(main())
